<template>
<section class="currency-panel" :class="{'currency-dark':dark}" aria-labelledby="currency-title">
<header><div><h2 id="currency-title">⇄ 多币种费用换算</h2><p>输入一笔费用，同时查看多种货币下的预计支出</p></div><button type="button" @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'收起':'展开'}}</button></header>
<template v-if="expanded">
<div class="currency-inputs"><label>费用金额<input v-model="amount" type="number" min="0" max="1000000000000" step="0.01" /></label><label>原币种<el-select v-model="from" aria-label="原币种" class="currency-select" :popper-class="dark ? 'currency-rates-dropdown-dark' : ''"><template #prefix><img class="currency-flag" :src="flagUrl(from)" alt="" aria-hidden="true" /></template><el-option v-for="c in currencies" :key="c.code" :value="c.code" :label="`${c.code} · ${c.name}`"><span class="currency-option"><img class="currency-flag" :src="flagUrl(c.code)" alt="" aria-hidden="true" />{{c.code}} · {{c.name}}</span></el-option></el-select></label><label>附加手续费（%）<input v-model="fee" type="number" min="0" max="100" step="0.1" /></label><label>固定手续费（{{from}}）<input v-model="fixed" type="number" min="0" step="0.01" /></label></div>
<p class="currency-status" role="status">{{error?'刷新失败，使用上次汇率 · ':''}}{{rateDate ? `汇率日期 ${rateDate}` : loading?'正在加载汇率…':'暂无汇率'}}<span v-if="stale"> · 较早的参考汇率</span></p>
<p v-if="invalid" class="currency-error" role="alert">请输入有效非负金额与手续费，费率范围为 0–100%。</p>
<div v-else-if="rows.length" class="currency-grid"><article v-for="row in rows" :key="row.code"><div class="currency-name"><img class="currency-flag" :src="flagUrl(row.code)" alt="" aria-hidden="true" />{{row.name}} <span>{{row.code}}</span></div><strong>{{money(row.result,row.code)}}</strong><small>1 {{from}} ≈ {{rate(row.rate)}} {{row.code}}</small></article></div>
<p v-if="rows.length&&!invalid" class="currency-total">含手续费总支出：{{money(rows[0].total,from)}} {{from}}。费用计算：金额 ×（1 + 手续费率）+ 固定手续费；手续费均按原币种额外计入。</p>
<button v-if="error" type="button" @click="load">重新加载汇率</button>
<footer>数据：<a href="https://frankfurter.dev/" target="_blank" rel="noopener noreferrer">Frankfurter / 欧洲央行参考汇率</a>。工作日更新，周末及节假日可能沿用上一工作日；仅供费用估算，银行点差、实际结算汇率及其他费用未计入。</footer>
</template>
</section>
</template>
<script>
import {convertExpense} from '../utils/currency-converter.mjs';
const currencies=[['CNY','人民币'],['USD','美元'],['EUR','欧元'],['HKD','港币'],['JPY','日元'],['GBP','英镑'],['AUD','澳元'],['CAD','加元'],['SGD','新加坡元'],['CHF','瑞士法郎'],['KRW','韩元'],['THB','泰铢']].map(([code,name])=>({code,name}));
export default {name:'CurrencyConverter',props:{dark:Boolean},data:()=>({expanded:true,amount:'100',from:'CNY',fee:'0',fixed:'0',rates:{},rateDate:'',loading:false,error:false,controller:null,currencies}),computed:{invalid(){return [this.amount,this.fee,this.fixed].some(v=>String(v).trim()===''||!Number.isFinite(Number(v))||Number(v)<0)||Number(this.fee)>100||Number(this.amount)>1e12;},rows(){if(this.invalid)return [];return this.currencies.map(c=>({...c,...convertExpense(Number(this.amount),Number(this.fee),Number(this.fixed),this.from,c.code,this.rates)})).filter(r=>Number.isFinite(r.result));},stale(){return this.rateDate&&Date.now()-Date.parse(this.rateDate+'T00:00:00Z')>4*86400000;}},mounted(){this.load();},beforeUnmount(){this.controller?.abort();},methods:{flagUrl(code){const flags={CNY:'cn',USD:'us',EUR:'eu',HKD:'hk',JPY:'jp',GBP:'gb',AUD:'au',CAD:'ca',SGD:'sg',CHF:'ch',KRW:'kr',THB:'th'};return `${process.env.BASE_URL}country-flags/${flags[code]}.svg`;},money(n,code){return n.toLocaleString('zh-CN',{minimumFractionDigits:['JPY','KRW'].includes(code)?0:2,maximumFractionDigits:['JPY','KRW'].includes(code)?0:2});},rate(n){return n.toLocaleString('zh-CN',{maximumFractionDigits:6});},accept(data){if(data?.base!=='USD'||!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||!Number.isFinite(Date.parse(data.date))||data.rates?.USD!==1)throw Error('invalid FX');const rates=Object.fromEntries(Object.entries(data.rates).filter(([k,v])=>/^[A-Z]{3}$/.test(k)&&typeof v==='number'&&Number.isFinite(v)&&v>0));if(!rates.CNY||!rates.EUR)throw Error('incomplete FX');this.rates=rates;this.rateDate=data.date;},async load(){this.error=false;this.loading=true;try{const d=JSON.parse(localStorage.getItem('currency-rates-v1'));if(d)this.accept(d);}catch{/* optional cache */}this.controller=new AbortController();const timeout=setTimeout(()=>this.controller.abort(),12000);try{const r=await fetch(`${process.env.BASE_URL}exchange-rates.json`,{cache:'no-cache',signal:this.controller.signal});if(!r.ok)throw Error('FX request');const d=await r.json();this.accept(d);try{localStorage.setItem('currency-rates-v1',JSON.stringify(d));}catch{/* optional cache */}}catch{this.error=true;}finally{clearTimeout(timeout);this.loading=false;}}}};
</script>
<style scoped>
.currency-panel{--fx-text:#26364c;--fx-muted:#7b8799;--fx-line:rgba(105,128,160,.15);margin:18px 0 24px;padding:22px 24px;border:1px solid var(--fx-line);border-radius:18px;background:rgba(255,255,255,.86);color:var(--fx-text)}.currency-dark{--fx-text:#e2e9f4;--fx-muted:#95a3b9;--fx-line:rgba(145,164,194,.17);background:rgba(24,31,45,.92)}header{display:flex;justify-content:space-between;align-items:center;gap:12px}h2{margin:0;font-size:18px}header p{font-size:12px;color:var(--fx-muted);margin:8px 0 0}button{border:0;border-radius:7px;background:rgba(64,141,143,.08);color:var(--fx-muted);padding:7px 10px;cursor:pointer}input,select{box-sizing:border-box;width:100%;min-width:0;padding:10px;border:1px solid var(--fx-line);border-radius:8px;color:var(--fx-text);background:transparent;font:inherit;font-size:13px}select option{color:#26364c;background:white}.currency-inputs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:22px 0 12px}label{display:flex;flex-direction:column;gap:8px;font-size:12px;color:var(--fx-muted)}.currency-status,.currency-total{font-size:11px;line-height:1.8;color:var(--fx-muted)}.currency-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.currency-grid article{border:1px solid var(--fx-line);border-radius:10px;padding:14px;min-width:0;overflow-wrap:anywhere}.currency-grid article>div{font-size:12px}.currency-grid span{color:var(--fx-muted);font-size:10px;margin-left:5px}.currency-grid strong{display:block;margin:12px 0;font-size:22px;font-variant-numeric:tabular-nums;color:#43898d}.currency-grid small{font-size:10px;color:var(--fx-muted)}footer{font-size:10px;color:var(--fx-muted);line-height:1.8;margin-top:16px}footer a{color:inherit}.currency-error{color:#d75c60;font-size:12px}input:focus-visible,select:focus-visible,button:focus-visible{outline:2px solid #43898d;outline-offset:2px}@media(max-width:700px){.currency-panel{padding:18px 16px}.currency-inputs{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.currency-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.currency-grid strong{font-size:19px}}
</style>

<style scoped>
.currency-flag{display:inline-block;width:24px;height:18px;object-fit:cover;border-radius:3px;flex-shrink:0;box-shadow:0 0 0 1px rgba(127,145,171,.16)}
.currency-name,.currency-option{display:flex;align-items:center;gap:8px}.currency-name{flex-wrap:wrap}.currency-name>span{margin-left:0}.currency-select{width:100%;min-width:0}.currency-select :deep(.el-select__wrapper){min-height:38px;background:transparent;box-shadow:0 0 0 1px var(--fx-line) inset}.currency-select :deep(.el-select__selected-item){color:var(--fx-text)}
</style>
